    public static void AlignUnifiedRoadToFlatGround() {
        string flag=Path.Combine(Reports,"town-unified-flat-ground-repair.json");if(File.Exists(flag))throw new Exception("Flat-ground alignment already applied; inspect receipt");
        var data=JsonUtility.FromJson<UnifiedGeometry>(File.ReadAllText(Path.Combine(Reports,"town-unified-road-geometry.json")));var build=JsonUtility.FromJson<UnifiedRoadReceipt>(File.ReadAllText(Path.Combine(Reports,"town-unified-road-build.json")));
        var scenes=LoadIsland();var all=scenes.SelectMany(All).ToArray();IndexRevisionObjects(all);var root=all.Single(t=>t.name=="TownRoadNetwork20261019");var lands=all.Select(t=>t.GetComponent<Terrain>()).Where(t=>t&&t.gameObject.activeInHierarchy).ToArray();var baseline=JsonUtility.FromJson<PlanningInventory>(File.ReadAllText(Path.Combine(Reports,"town-unified-inventory.json")));foreach(var p in baseline.protectedNodes){var t=Resolve<Transform>(p.globalId);if(!t||Signature(t)!=p.signature)throw new Exception("Flat alignment protected drift "+p.path);}
        var receipt=new FlatRoadEdgeReceipt{utc=DateTime.UtcNow.ToString("o"),minimumGround=float.MaxValue,minimumParkGrass=1};
        var alpha=lands.ToDictionary(t=>t,t=>t.terrainData.GetAlphamaps(0,0,t.terrainData.alphamapWidth,t.terrainData.alphamapHeight));
