        foreach(var surface in data.surfaces){var owner=SurfaceOwner(surface,root,all);CopyUpdatedMesh(owner,UnifiedMesh(surface,owner,data,null));}
        var kerbs=new RoadGeometry();foreach(var ring in data.curbInnerRings)for(int i=0;i<ring.points.Length-1;i++){var a=ring.points[i];var b=ring.points[i+1];a.y=b.y=data.curbTopY;kerbs.Wall(a,b,data.asphaltY,data.asphaltY);}var kerbOwner=root.Find("ContinuousSurfaces/Unified_CurbFaces");CopyUpdatedMesh(kerbOwner,WallMesh(kerbs,kerbOwner,"Unified_CurbFaces"));
        var walls=new RoadGeometry();foreach(var ring in data.outerPavingRings)for(int i=0;i<ring.points.Length-1;i++){var a=ring.points[i];var b=ring.points[i+1];int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/.5f));for(int j=0;j<n;j++){var x=Vector3.Lerp(a,b,(float)j/n);var z=Vector3.Lerp(a,b,(float)(j+1)/n);x.y=z.y=data.curbTopY;walls.Wall(x,z,PlanningGround(lands,x.x,x.z)-.025f,PlanningGround(lands,z.x,z.z)-.025f);}}var wallOwner=root.Find("ContinuousSurfaces/Unified_OuterRoadbed");CopyUpdatedMesh(wallOwner,WallMesh(walls,wallOwner,"Unified_OuterRoadbed"));
        foreach(var road in data.plan.roads)root.Find("RoadSections/"+road.id).position=new Vector3((road.a.x+road.b.x)/2,data.asphaltY,(road.a.z+road.b.z)/2);
        foreach(var parcel in data.plan.plots){var t=root.Find("YellowParcelReservations").Cast<Transform>().Single(p=>p.name.StartsWith(parcel.id+"_"));var before=build.plan.plots.Single(p=>p.id==parcel.id);if(Mathf.Abs(before.width-parcel.width)>.001f||Mathf.Abs(before.depth-parcel.depth)>.001f)throw new Exception("Parcel dimensions changed");if(Vector2.Distance(new Vector2(before.x,before.z),new Vector2(parcel.x,parcel.z))>.001f)receipt.movedParcels++;t.position=new Vector3(parcel.x,PlanningGround(lands,parcel.x,parcel.z),parcel.z);PrefabUtility.SaveAsPrefabAsset(t.gameObject,build.assets+"/Prefabs/"+parcel.id+"_Parcel.prefab");}
