        if(!build.terrains.All(before=>SameTerrain(before,FullTerrain(lands.Single(t=>P(t.transform)==before.path)))))throw new Exception("Terrain modified");
        foreach(var p in baseline.protectedNodes){var t=Resolve<Transform>(p.globalId);if(!t||Signature(t)!=p.signature)throw new Exception("Protected object changed during edge correction "+p.path);}
